anded="false" aria-controls="faq-answer-3"><span class="faq-title"><h3 id="what-generation-uses-instagram-the-most">What generation uses Instagram the most?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-3" class="faq-answer" role="region" aria-hidden="true">Millennials and Gen Z. Users aged 25 to 34 are the biggest group, followed by those aged 18 to 24.</div></div><div class="faq-item"><button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-answer-4"><span class="faq-title"><h3 id="how-can-instagram-dm-automation-help-businesses">How can Instagram DM automation help businesses?</h3></span><span class="faq-arrow" aria-hidden="true"></span></button><div id="faq-answer-4" class="faq-answer" role="region" aria-hidden="true">Instagram DM automation helps businesses automate replies, answer enquiries, engage potential customers, and guide shoppers toward purchases.</div></div></div><script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Which country has the highest number of Instagram users in 2026?","acceptedAnswer":{"@type":"Answer","text":"India has the highest number of Instagram users with approximately 480.55 million users. Followed by the United States in second place with 185.55 million users."}},{"@type":"Question","name":"What Instagram benchmarks should big brands use to measure success?","acceptedAnswer":{"@type":"Answer","text":"The Instagram benchmarks that businesses should use to measure success include follower growth, engagement rate, reach, and impressions."}},{"@type":"Question","name":"Which type of content performs best on Instagram in 2026?","acceptedAnswer":{"@type":"Answer","text":"Carousels lead in engagement (about 0.55%), with Reels close behind (about 0.52%). Reels are best for reaching new people and drawing comments, so test both."}},{"@type":"Question","name":"What generation uses Instagram the most?","acceptedAnswer":{"@type":"Answer","text":"Millennials and Gen Z. Users aged 25 to 34 are the biggest group, followed by those aged 18 to 24."}},{"@type":"Question","name":"How can Instagram DM automation help businesses?","acceptedAnswer":{"@type":"Answer","text":"Instagram DM automation helps businesses automate replies, answer enquiries, engage potential customers, and guide shoppers toward purchases."}}]}</script>
    <script>
    (function(){
        if (window.__customFaqAccordionInit) return;
        window.__customFaqAccordionInit = true;

        function closeAnswer(answer, btn) {
            if (!answer) return;
            // if maxHeight is "none", set to current px value to animate to 0
            if (answer.style.maxHeight === "none" || answer.style.maxHeight === "") {
                answer.style.maxHeight = answer.scrollHeight + "px";
            }
            // force reflow
            void answer.offsetHeight;
            answer.style.maxHeight = "0px";
            answer.classList.remove("open");
            if (btn) {
                btn.classList.remove("open");
                btn.setAttribute("aria-expanded", "false");
            }
            answer.setAttribute("aria-hidden", "true");
        }

        function openAnswer(answer, btn) {
            if (!answer) return;
            // set to exact height so transition works
            answer.style.maxHeight = answer.scrollHeight + "px";
            answer.classList.add("open");
            if (btn) {
                btn.classList.add("open");
                btn.setAttribute("aria-expanded", "true");
            }
            answer.setAttribute("aria-hidden", "false");

            // once transition finishes, set to none to allow internal content changes (images) without clipping
            var onTransEnd = function(e){
                if (answer.classList.contains("open")) {
                    answer.style.maxHeight = "none";
                }
                answer.removeEventListener("transitionend", onTransEnd);
            };
            answer.addEventListener("transitionend", onTransEnd);
        }

        document.addEventListener("click", function(e){
            var btn = e.target.closest ? e.target.closest(".custom-faq-accordion .faq-question") : null;
            if (!btn) return;

            var item = btn.closest(".faq-item");
            if (!item) return;
            var answer = item.querySelector(".faq-answer");
            if (!answer) return;

            // if already open, close it
            if (answer.classList.contains("open")) {
                closeAnswer(answer, btn);
            } else {
                // optionally close other open items (uncomment to allow only-one-open)
                var openItems = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
                openItems.forEach(function(o){
                    var parentBtn = o.closest(".faq-item") ? o.closest(".faq-item").querySelector(".faq-question") : null;
                    if (o !== answer) closeAnswer(o, parentBtn);
                });

                openAnswer(answer, btn);
            }
        });

        // Make sure open answers recalc height on window resize (useful if images load or layout changes)
        window.addEventListener("resize", function(){
            var openAnswers = document.querySelectorAll(".custom-faq-accordion .faq-answer.open");
            openAnswers.forEach(function(a){
                // if maxHeight is "none", set it to scrollHeight to keep it visible after resize
                if (a.style.maxHeight === "none") {
                    a.style.maxHeight = a.scrollHeight + "px";
                    // then release to none after a tick
                    setTimeout(function(){ a.style.maxHeight = "none"; }, 350);
                }
            });
        });
    })();
    </script>
    
